CREATE TABLE IF NOT EXISTS report2_command_v2(command_id TEXT PRIMARY KEY,mode TEXT NOT NULL,contract TEXT,request_channel TEXT NOT NULL,received_at INTEGER NOT NULL,deadline INTEGER NOT NULL,generation TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('ACCEPTED','QUEUED','RUNNING','COMPLETED','FAILED','EXPIRED')),lease_owner TEXT,lease_until INTEGER,result_snapshot_id TEXT,rendered_text_hash TEXT,error TEXT,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS report2_publication_v2(publication_id TEXT PRIMARY KEY,run_id TEXT NOT NULL,snapshot_id TEXT NOT NULL,wave_id TEXT NOT NULL,contract TEXT NOT NULL,direction TEXT NOT NULL,event TEXT,generation TEXT NOT NULL,text TEXT NOT NULL,payload_hash TEXT NOT NULL,created_ts INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS report2_dispatch_v2(dispatch_id TEXT PRIMARY KEY,publication_id TEXT NOT NULL,payload_hash TEXT NOT NULL,recipient_identity TEXT NOT NULL,state TEXT NOT NULL,attempts INTEGER NOT NULL,lease_until INTEGER,message_id INTEGER,message_date INTEGER,response_ts INTEGER,sent_ts INTEGER,created_ts INTEGER NOT NULL,FOREIGN KEY(publication_id) REFERENCES report2_publication_v2(publication_id));
